(()=>{'use strict';const key='zuxuru-fashion-service-v1',$=id=>document.getElementById(id),form=$('store-design-form');let files=[];const state=()=>JSON.parse(localStorage.getItem(key)||'{"designer":{},"products":[],"evidence":[],"orders":[]}'),notify=t=>$('store-editor-status').textContent=t;function select(id,type,value){const s=document.createElement('select');if(id)s.id=id;s.append(new Option('None — keep private',''));files.filter(f=>f.content_type.startsWith(type)).forEach(f=>s.append(new Option(f.name,f.id)));s.value=value||'';return s;}
function render(){const base=state(),d=base.storefront||{};for(const k of ['headline','intro','theme','accent','email','whatsapp','delivery','returns'])form.elements[k].value=d[k]||(k==='theme'?'dark':k==='accent'?'#d4af37':'');form.elements.socials.value=(d.socials||[]).map(s=>s.label+' | '+s.url).join('\n');for(const [id,name,type] of [['store-hero','heroId','image/'],['store-video','videoId','video/']]){const old=$(id),next=select(id,type,d[name]);next.name=name;old.replaceWith(next);}const gallery=$('store-gallery');gallery.replaceChildren();files.filter(f=>/^(image|video)\//.test(f.content_type)).forEach(f=>{const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=f.id;check.name='galleryIds';check.checked=(d.galleryIds||[]).includes(f.id);check.style.width='auto';label.append(check,document.createTextNode(' '+f.name));gallery.append(label);});const products=$('store-product-media');products.replaceChildren();if(!base.products.length)products.textContent='Add your designs in Collection & costing first.';base.products.forEach(p=>{const card=document.createElement('article');card.className='record';card.dataset.productId=p.id;const h=document.createElement('h3');h.textContent=p.name;card.append(h);for(const [name,title,type]of [['imageId','Product photograph','image/'],['videoId','Product film','video/']]){const label=document.createElement('label');label.textContent=title;const s=select('',type,p[name]);s.dataset.field=name;label.append(s);card.append(label);}products.append(card);});}
async function reload(){try{const r=await fetch('/api/designer/media'),d=await r.json();if(!r.ok)throw Error(d.error);files=d.files;render();notify('Choose media placements and save your website draft.');}catch(e){notify(e.message);}}
form.onsubmit=e=>{e.preventDefault();const base=state(),v=Object.fromEntries(new FormData(form));v.galleryIds=[...form.querySelectorAll('[name="galleryIds"]:checked')].map(e=>e.value).slice(0,12);v.socials=v.socials.split('\n').map(line=>{const [label,...rest]=line.split('|');return {label:label.trim(),url:rest.join('|').trim()};}).filter(s=>s.label&&s.url);if(v.whatsapp&&!/^\+?[0-9]{8,15}$/.test(v.whatsapp)){notify('Use a WhatsApp number with country code and digits only.');return;}base.storefront=v;for(const card of $('store-product-media').children){const p=base.products.find(p=>p.id===card.dataset.productId);if(p)card.querySelectorAll('select').forEach(s=>p[s.dataset.field]=s.value);}localStorage.setItem(key,JSON.stringify(base));document.dispatchEvent(new Event('fashion-storefront-updated'));notify('Website draft saved. Wait for Cloud saved before previewing or publishing.');};
$('store-media-reload').onclick=reload;$('store-live-preview').onclick=()=>{if(!window.designerCloudReady?.()){notify('Save your draft and wait for Cloud saved first.');return;}const frame=$('store-preview-frame');frame.src='/api/designer/storefront-preview?time='+Date.now();frame.hidden=false;};$('store-use-home').onclick=async()=>{if(!confirm('Use your published collection as the main Bonga Bhengu website?'))return;try{const r=await fetch('/api/designer/homepage',{method:'POST'}),d=await r.json();if(!r.ok)throw Error(d.error);notify('Your published storefront is now the main website.');}catch(e){notify(e.message);}};$('store-restore-home').onclick=async()=>{if(!confirm('Restore the original Bonga Bhengu homepage? Your designer storefront stays published.'))return;try{const r=await fetch('/api/designer/homepage',{method:'DELETE'}),d=await r.json();if(!r.ok)throw Error(d.error);notify('Original website restored.');}catch(e){notify(e.message);}};fetch('/api/jarvis/status').then(r=>r.json()).then(s=>{$('store-use-home').hidden=!s.owner;$('store-restore-home').hidden=!s.owner;}).catch(()=>{});window.addEventListener('hashchange',()=>{if(location.hash==='#storefront-editor')reload();});reload();
})();
